export const SLIDE_WIDTH_PX = 1280
export const SLIDE_HEIGHT_PX = 720
export const SLIDE_WIDTH_IN = 13.333333
export const SLIDE_HEIGHT_IN = 7.5

export interface ElementBox { x: number; y: number; w: number; h: number }

export interface TextRunIR {
  text: string
  fontFamily: string
  fontSizePx: number
  fontWeight: number
  fontStyle: string
  color: string
  textDecoration: string
}

export interface ElementStyleIR {
  fontFamily: string
  fontSizePx: number
  fontWeight: number
  fontStyle: string
  color: string
  backgroundColor: string
  backgroundImage: string
  borderColor: string
  borderWidthPx: number
  borderStyle: string
  borderRadius: string
  textAlign: string
  verticalAlign: string
  lineHeightPx: number
  /** Computed letter-spacing in px; `normal` becomes 0 so PPTX can carry tracking. */
  letterSpacingPx: number
  /** Computed text-transform; `uppercase` labels are exported as uppercase text. */
  textTransform: string
  /** Pure CSS rotation in degrees, clockwise; 0 for every unrotated leaf. */
  rotationDeg: number
  opacity: number
  objectFit: string
  objectPosition: string
}

export interface ElementIR {
  id: string
  kind: 'text' | 'image' | 'shape' | 'svg' | 'table'
  z: number
  domOrder: number
  box: ElementBox
  style: ElementStyleIR
  text?: string
  runs?: TextRunIR[]
  imagePath?: string
  svg?: string
  table?: string[][]
  /**
   * Native DrawingML for a shape pptxgenjs cannot express (custom geometry,
   * in-shape gradient, dash pattern, arrowheads). The writer adds a placeholder
   * rectangle named `id` and then rewrites that `<p:sp>` in the finished
   * package from this plan. When absent the shape is a plain preset shape.
   */
  nativeShape?: import('./svg-ooxml.ts').ShapeSpec
  /**
   * Suppress renderer line wrapping for this text leaf. The SVG lane breaks
   * lines itself (one authored line per box), so PowerPoint must not re-wrap a
   * measured line at its box edge.
   */
  noWrap?: boolean
  unsupportedReason?: string
}

export interface SlideBackgroundIR {
  /** Computed CSS background-color, e.g. `rgb(8, 17, 32)`; empty/`transparent` allowed. */
  color: string
  /** Computed CSS background-image; `none` when absent, otherwise e.g. `linear-gradient(160deg, rgb(8, 17, 32) 0%, rgb(16, 41, 77) 55%, rgb(11, 58, 107) 100%)`. */
  image: string
}

export interface SlideIR {
  page: number
  elements: ElementIR[]
  speakerNotes: string[]
  background?: SlideBackgroundIR
}

export interface DeckIR {
  widthPx: typeof SLIDE_WIDTH_PX
  heightPx: typeof SLIDE_HEIGHT_PX
  slides: SlideIR[]
}

export function roundFixed(value: number, digits = 6): number {
  const factor = 10 ** digits
  return Math.round((value + Number.EPSILON) * factor) / factor
}

export function pxToInches(value: number): number {
  return roundFixed(value / 96)
}

export function pxToPoints(value: number): number {
  return roundFixed(value * 0.75, 2)
}
